val timeOfDay = when (hour) {
    in 5..11 -> "Morning"
    in 12..16 -> "Afternoon"
    in 17..20 -> "Evening"
    else -> "Night"
}

val rating = when {
    score >= 90 -> "Excellent"
    score >= 70 -> "Good"
    score >= 50 -> "Fair"
    else -> "Poor"
}

val ageGroup = when {
    age < 13 -> "Child"
    age < 20 -> "Teen"
    age < 60 -> "Adult"
    else -> "Senior"
}

val season = when (month) {
    12, 1, 2 -> "Winter"
    3, 4, 5 -> "Spring"
    6, 7, 8 -> "Summer"
    else -> "Fall"
}

val priority = when (level) {
    in 1..3 -> "Low"
    in 4..6 -> "Medium"
    in 7..10 -> "High"
    else -> "Invalid"
}

val colorClass = when {
    red > 128 && red > green && red > blue -> "Red"
    green > 128 && green > red && green > blue -> "Green"
    blue > 128 && blue > red && blue > green -> "Blue"
    else -> "Gray"
}

val condition = if (temp > 25) {
    if (humidity > 60) "Hot+Humid" else "Hot+Dry"
} else {
    if (humidity > 60) "Cold+Humid" else "Cold+Dry"
}

#!/bin/bash
source ~/ollama-local/lib/sh/multiternary.sh
size=$1
class=$(range_ternary "$size" "0,1024" "Tiny" "1024,10485760" "Small" "10485760,104857600" "Medium" "104857600,999999999" "Large")
echo "$class"

when {
    x < 10 -> return "A"
    x < 20 -> return "B"
    else -> return "C"
}

val greeting = when (hour) {
    in 6..11 -> "Good Morning"
    in 12..17 -> "Good Afternoon"
    in 18..23 -> "Good Evening"
    else -> "Good Night"
}

val layout = when {
    screenWidthDp < 400 -> R.layout.activity_phone
    screenWidthDp < 600 -> R.layout.activity_tablet
    else -> R.layout.activity_landscape
}

val exitClass = when {
    exitCode == 0 -> "Success"
    exitCode in 128..191 -> "Signal"
    exitCode in 1..127 -> "Standard"
    else -> "Unknown"
}

val primeClass = when {
    n == 2 -> "Even Prime"
    n > 2 && isPrime(n) && n % 2 == 1 -> "Odd Prime"
    else -> "Not Prime"
}

val memStatus = when {
    memPercent < 50 -> "Available"
    memPercent < 80 -> "Tight"
    memPercent < 95 -> "Critical"
    else -> "OutOfMemory"
}

val poolStatus = when (connectionState) {
    "closed" -> "NotInitialized"
    "open" -> "Available"
    "saturated" -> "Blocked"
    else -> "Unknown"
}

val variantProfile = when (buildVariant) {
    "debug" -> "Verbose"
    "release" -> "Optimized"
    "staging" -> "Balanced"
    else -> "Custom"
}

val comfortLevel = when (celsius) {
    in 18..24 -> "Comfortable"
    in 0..17 -> "Cold"
    else -> "Warm"
}
